class Scheduling
    def initialize(customer, days = 1)
      @customer = customer
      @pickup = Date.today + days
    end

    def receipt
      "#{@customer}: #{@pickup.iso8601}"
    end
  end

def initialize(customer, items, days = 1)
      super(customer, days)
      @items = items
      @status = :queued
    end

class Order < Scheduling
    attr_reader :items
    attr_accessor :status

    def initialize(customer, items, days = 1)
      super(customer, days)
      @items = items
      @status = :queued
    end
  end

def record(order, status)
      order.status = status
      @orders << order
      order.receipt
    end
